// VENDORED from the hitloop-video hub (clients/critters-quest/howto/requestToSpec.mjs) by scripts/sync-howto-catalog.mjs. Do not edit here.
// CQ-HowTo request (template v3.3, parsed YAML as an object) -> spec. PURE and deterministic: no LLM, no network, no clock.
// Shared by the Cloud Run service (services/showcase-render/job.mjs) and the owner scripts (scripts/howto-pull.mjs).
// requestToSpec(request, { catalog, campaign, publicDir? }) -> { ok:true, spec } | { ok:false, reasons:[string] }
// catalog = howto/catalog.json, campaign = howto/campaign.json (both generated by scripts/howto-catalog.mjs).
// Reasons are stable strings; <step> is the 1-based step number (the line id is step<step>):
//   missing:<dotted.path>  bad-id  steps-count  clicks-count:<step>  unknown-panel:<step>:<panel>  unknown-action:<step>:<action>
//   unknown-preset:<step>:<preset>  unknown-host:<name>  new-panels-required  art-missing:<path>
// v3.3 adds `skeleton: "cursor"` (no host, exact windows; see cursorToSpec below). Extra reasons for it:
//   unknown-skeleton:<v>  cursor-host-must-be-none  guide-host-none  cursor-narration-unsupported  seconds-invalid:<establish|n|end>
//   establish-too-short  step-too-short:<step>  end-too-short  total-too-long  unknown-view:<panel>  view-must-be-canvas
//   later-needs-completed-view:<step>
// Scene blocks (v3.3 "scene blocks"; src/howto/blocks): establish / steps may carry `scene: "<family>.<shot>"` (+ optional `variant`)
//   instead of view / panel+clicks. Reasons: unknown-scene:<step|establish>:<id>  unknown-variant:<step>:<id>:<variant>  scene-exclusive:<step>
//   later-not-allowed:<step>  scene-role:<step>:<id>  excluded-scene:<step>:<id>:<flag>  exclude-invalid  (request `exclude: [money|S3|realPlayers]`)
// (revised: the end shows the supplied image full-frame, so there is no crop; end.caption / end.cta / end.headline are optional post copy)
// The result spec carries vo {} and narration from the request; the VO stage fills vo, the job decides the effective narration.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { CURSOR_FPS, CURSOR_TIMING, minStepFrames } from "./cursorTiming.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ID_RE = /^[a-z0-9-]{3,48}$/;

/** Reads the generated catalog + campaign next to this file (or from `dir`). */
export const loadCatalog = (dir = HERE) => ({
  catalog: JSON.parse(fs.readFileSync(path.join(dir, "catalog.json"), "utf8")),
  campaign: JSON.parse(fs.readFileSync(path.join(dir, "campaign.json"), "utf8")),
});

const str = (v) => (typeof v === "string" && v.trim() ? v.trim() : "");
const isObj = (v) => v && typeof v === "object" && !Array.isArray(v);

const publicFile = (publicDir, rel) => {
  const root = path.resolve(publicDir);
  const file = path.resolve(root, rel);
  const r = path.relative(root, file);
  try { return !r.startsWith("..") && !path.isAbsolute(r) && fs.statSync(file).isFile() ? file : null; } catch { return null; }
};

/** frames = seconds * 30 must be a whole number of frames (a spec window is exact). */
const framesOf = (sec) => { const f = typeof sec === "number" ? sec * CURSOR_FPS : 0; return f > 0 && Math.abs(f - Math.round(f)) < 1e-6 ? Math.round(f) : 0; };

const EXCLUDE_FLAGS = ["money", "S3", "realPlayers"];
const flagHit = (flags, f) => (f === "money" ? flags?.money === true : f === "S3" ? flags?.season === "S3" : flags?.realPlayers === true);

/** Cursor skeleton (template v3.3): no host, no VO; establish -> steps (exact windows) -> end art. */
const cursorToSpec = (r, { catalog, publicDir }) => {
  const reasons = [];
  const miss = (p) => reasons.push(`missing:${p}`);
  const id = str(r.id);
  if (!id) miss("id"); else if (!ID_RE.test(id)) reasons.push("bad-id");
  if (!Number.isInteger(r.season)) miss("season");
  const label = str(r.label); if (!label) miss("label");
  const hostName = str(r.host?.name) || "none";
  if (hostName !== "none") reasons.push("cursor-host-must-be-none");
  if (r.narration === true) reasons.push("cursor-narration-unsupported");
  if (Array.isArray(r.new_panels) && r.new_panels.some((p) => isObj(p) && Object.values(p).some((v) => str(v) || (Array.isArray(v) && v.length)))) reasons.push("new-panels-required");
  const exclude = Array.isArray(r.exclude) ? r.exclude : [];
  if (r.exclude !== undefined && (!Array.isArray(r.exclude) || exclude.some((f) => !EXCLUDE_FLAGS.includes(f)))) reasons.push("exclude-invalid");
  const scenes = catalog.scenes ?? {};
  /** Validates a scene block reference for `who` ("establish" or the 1-based step) and role; returns its info or null. */
  const checkScene = (who, id, variant, role) => {
    const info = scenes[id];
    if (!info) { reasons.push(`unknown-scene:${who}:${id}`); return null; }
    if (!(info.roles ?? []).includes(role)) reasons.push(`scene-role:${who}:${id}`);
    for (const f of exclude) if (EXCLUDE_FLAGS.includes(f) && flagHit(info.flags, f)) reasons.push(`excluded-scene:${who}:${id}:${f}`);
    if (variant && !info.variants?.[variant]) reasons.push(`unknown-variant:${who}:${id}:${variant}`);
    return info;
  };
  let total = 0;

  // establish
  const estCaption = str(r.establish?.caption); if (!estCaption) miss("establish.caption");
  const estView = str(r.establish?.view);
  const estScene = str(r.establish?.scene);
  const estVariant = str(r.establish?.variant);
  if (estScene) {
    if (estView) reasons.push("scene-exclusive:establish");
    checkScene("establish", estScene, estVariant, "establish");
  }
  const estFrames = framesOf(r.establish?.seconds);
  if (!estFrames) { if (r.establish?.seconds === undefined) miss("establish.seconds"); else reasons.push("seconds-invalid:establish"); }
  else if (estFrames < CURSOR_TIMING.establishMin) reasons.push("establish-too-short");
  total += estFrames;
  let lastCanvas;
  if (estScene) lastCanvas = undefined;
  else if (estView) {
    if (!catalog.panels[estView]) reasons.push(`unknown-view:${estView}`);
    else if (catalog.panels[estView].surface !== "canvas") reasons.push("view-must-be-canvas");
    else lastCanvas = estView;
  } else if (catalog.panels.spotTileWide?.surface === "canvas") lastCanvas = "spotTileWide";

  // steps
  const steps = [];
  if (!Array.isArray(r.steps) || r.steps.length < 1 || r.steps.length > 6) reasons.push("steps-count");
  else {
    let sceneStart = 0; // running frame where the current (merged) scene began
    let prev = null;
    let at = estFrames;
    r.steps.forEach((s, i) => {
      const n = i + 1;
      const caption = str(s?.caption); if (!caption) miss(`steps.${n}.caption`);
      const sceneId = str(s?.scene);
      if (sceneId) {
        const variant = str(s?.variant);
        if (str(s?.panel) || str(s?.preset) || (Array.isArray(s?.clicks) && s.clicks.length)) reasons.push(`scene-exclusive:${n}`);
        if (s?.later === true) reasons.push(`later-not-allowed:${n}`);
        checkScene(n, sceneId, variant, "step");
        const sframes = framesOf(s?.seconds);
        if (!sframes) { if (s?.seconds === undefined) miss(`steps.${n}.seconds`); else reasons.push(`seconds-invalid:${n}`); }
        else if (sframes < CURSOR_TIMING.sceneMin) reasons.push(`step-too-short:${n}`);
        steps.push({ caption, seconds: s?.seconds, scene: sceneId, ...(variant ? { variant } : {}) });
        prev = { panel: sceneId, later: false };
        at += sframes;
        total += sframes;
        return;
      }
      const panel = str(s?.panel);
      const info = catalog.panels[panel];
      if (!panel) miss(`steps.${n}.panel`); else if (!info) reasons.push(`unknown-panel:${n}:${panel}`);
      const preset = str(s?.preset);
      if (preset && info && !info.presets.includes(preset)) reasons.push(`unknown-preset:${n}:${preset}`);
      const clicks = Array.isArray(s?.clicks) ? s.clicks : [];
      if (!clicks.length) miss(`steps.${n}.clicks`); else if (clicks.length > 3) reasons.push(`clicks-count:${n}`);
      const actions = clicks.map((c, k) => {
        const a = str(c?.action);
        if (!a) miss(`steps.${n}.clicks.${k + 1}.action`);
        else if (info && !info.actions.includes(a)) reasons.push(`unknown-action:${n}:${a}`);
        return a;
      });
      const frames = framesOf(s?.seconds);
      if (!frames) { if (s?.seconds === undefined) miss(`steps.${n}.seconds`); else reasons.push(`seconds-invalid:${n}`); }
      const later = s?.later === true;
      const newScene = !prev || prev.later || prev.panel !== panel || !!preset;
      if (newScene) sceneStart = at;
      if (frames && info && actions.every((a) => a)) {
        const timing = actions.map((a) => info.actionTiming?.[a] ?? {});
        const min = minStepFrames(timing, { later, panelMin: newScene ? info.minFrames ?? 0 : 0, local0: at - sceneStart });
        if (frames < min) reasons.push(`step-too-short:${n}`);
      }
      if (later) {
        const lp = lastCanvas && catalog.panels[lastCanvas];
        if (!lp || !(lp.presets.includes("ready") || lp.presets.includes("completed"))) reasons.push(`later-needs-completed-view:${n}`);
      }
      if (info?.surface === "canvas") lastCanvas = panel;
      const say = str(s?.say);
      steps.push({ caption, seconds: s?.seconds, panel, ...(preset ? { preset } : {}), actions, ...(later ? { later: true } : {}), ...(say ? { say } : {}) });
      prev = { panel, later };
      at += frames;
      total += frames;
    });
  }

  // end: the supplied image full-frame as is (art) or the approved end card with the campaign headline (no art)
  const endFrames = framesOf(r.end?.seconds);
  if (!endFrames) { if (r.end?.seconds === undefined) miss("end.seconds"); else reasons.push("seconds-invalid:end"); }
  else if (endFrames < CURSOR_TIMING.endMin) reasons.push("end-too-short");
  total += endFrames;
  const src = str(r.end?.art?.src);
  if (publicDir && src && !publicFile(publicDir, src)) reasons.push(`art-missing:${src}`);
  const endCaption = str(r.end?.caption); // post copy only: never drawn
  const cta = str(r.end?.cta);
  const headline = str(r.end?.headline);
  if (total > 900) reasons.push("total-too-long");

  if (reasons.length) return { ok: false, reasons };
  return {
    ok: true,
    spec: {
      v: 1,
      skeleton: "cursor",
      id,
      mode: "final",
      season: r.season,
      host: "none",
      label,
      establish: { caption: estCaption, seconds: r.establish.seconds, ...(estView ? { view: estView } : {}), ...(estScene ? { scene: estScene } : {}), ...(estScene && estVariant ? { variant: estVariant } : {}) },
      steps,
      end: { seconds: r.end.seconds, ...(src ? { art: { src } } : {}), ...(headline ? { headline } : {}), ...(endCaption ? { caption: endCaption } : {}), ...(cta ? { cta } : {}) },
      music: true,
      narration: false,
      vo: {},
    },
  };
};

export const requestToSpec = (request, { catalog, campaign, publicDir } = {}) => {
  const reasons = [];
  const miss = (p) => reasons.push(`missing:${p}`);
  if (!isObj(request)) return { ok: false, reasons: ["missing:request"] };
  const r = request;
  if (r.skeleton !== undefined && r.skeleton !== "guide" && r.skeleton !== "cursor") return { ok: false, reasons: [`unknown-skeleton:${String(r.skeleton).slice(0, 20)}`] };
  if (r.skeleton === "cursor") return cursorToSpec(r, { catalog, campaign, publicDir });

  const id = str(r.id);
  if (!id) miss("id"); else if (!ID_RE.test(id)) reasons.push("bad-id");
  if (!Number.isInteger(r.season)) miss("season");
  const banner = str(r.banner); if (!banner) miss("banner");
  const hook = str(r.hook); if (!hook) miss("hook");
  const arrivalSay = str(r.arrival?.say); if (!arrivalSay) miss("arrival.say");
  const payoffSay = str(r.payoff?.say); if (!payoffSay) miss("payoff.say");
  const spotArt = str(r.payoff?.spot_art); if (!spotArt) miss("payoff.spot_art");
  const townName = str(r.payoff?.town?.name); if (!townName) miss("payoff.town.name");
  const townLevel = r.payoff?.town?.level;
  if (!Number.isInteger(townLevel) || townLevel < 1 || townLevel > 15) miss("payoff.town.level");

  const hostName = str(r.host?.name) || "mayor";
  if (hostName === "none") reasons.push("guide-host-none");
  else if (!catalog.hosts.includes(hostName)) reasons.push(`unknown-host:${hostName}`);

  if (Array.isArray(r.new_panels) && r.new_panels.some((p) => isObj(p) && Object.values(p).some((v) => str(v) || (Array.isArray(v) && v.length)))) reasons.push("new-panels-required");

  const steps = [];
  if (!Array.isArray(r.steps) || r.steps.length < 2 || r.steps.length > 4) reasons.push("steps-count");
  else r.steps.forEach((s, i) => {
    const n = i + 1;
    const say = str(s?.say); if (!say) miss(`steps.${n}.say`);
    const panel = str(s?.panel);
    if (!panel) miss(`steps.${n}.panel`);
    else if (!catalog.panels[panel]) reasons.push(`unknown-panel:${n}:${panel}`);
    const preset = str(s?.preset);
    if (preset && catalog.panels[panel] && !catalog.panels[panel].presets.includes(preset)) reasons.push(`unknown-preset:${n}:${preset}`);
    const clicks = Array.isArray(s?.clicks) ? s.clicks : [];
    if (!clicks.length) miss(`steps.${n}.clicks`);
    else if (clicks.length > 3) reasons.push(`clicks-count:${n}`);
    const actions = clicks.map((c, k) => {
      const a = str(c?.action);
      if (!a) miss(`steps.${n}.clicks.${k + 1}.action`);
      else if (catalog.panels[panel] && !catalog.panels[panel].actions.includes(a)) reasons.push(`unknown-action:${n}:${a}`);
      return a;
    });
    steps.push({ say, panel, ...(preset ? { preset } : {}), actions });
  });

  if (publicDir && spotArt) {
    const root = path.resolve(publicDir);
    const file = path.resolve(root, spotArt);
    const rel = path.relative(root, file);
    let ok = false;
    try { ok = !rel.startsWith("..") && !path.isAbsolute(rel) && fs.statSync(file).isFile(); } catch { /* missing */ }
    if (!ok) reasons.push(`art-missing:${spotArt}`);
  }

  if (reasons.length) return { ok: false, reasons };
  return {
    ok: true,
    spec: {
      v: 1,
      id,
      mode: "final",
      season: r.season,
      host: hostName,
      poster: { banner, bubble: campaign.poster.bubble, say: `${campaign.poster.sayPrefix} <break time="0.6s" /> ${hook}` },
      arrival: { say: arrivalSay },
      steps,
      payoff: { say: payoffSay, spot: { art: spotArt }, town: { name: townName, level: townLevel } },
      end: { say: campaign.end.say },
      music: true,
      narration: r.narration !== false,
      vo: {},
    },
  };
};
